#include "../runtime/apps/language/package.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct harness{const char*root;FILE*files[8];unsigned allocated,released;int fail_alloc,fail_read;};
static void path(struct harness*h,const char*p,char out[2048]){assert(!strncmp(p,"/contents/",10));int n=snprintf(out,2048,"%s%s",h->root,p+9);assert(n>0&&n<2048);}
static int open_read(void*c,const char*p){struct harness*h=c;char b[2048];path(h,p,b);for(unsigned i=0;i<8;i++)if(!h->files[i]){h->files[i]=fopen(b,"rb");return h->files[i]?(int)i:-1;}return -1;}
static int read_bytes(void*c,int fd,void*p,unsigned n){struct harness*h=c;assert(fd>=0&&fd<8&&h->files[fd]);if(h->fail_read)return -1;unsigned got=(unsigned)fread(p,1,n,h->files[fd]);return ferror(h->files[fd])?-1:(int)got;}
static int close_read(void*c,int fd){struct harness*h=c;assert(fd>=0&&fd<8&&h->files[fd]);int n=fclose(h->files[fd]);h->files[fd]=0;return n;}
static void*allocate(void*c,unsigned n){struct harness*h=c;if(h->fail_alloc)return 0;assert(n<=HB_LP_STX_MAX);void*p=malloc(n);if(p)h->allocated++;return p;}
static void release(void*c,void*p){struct harness*h=c;assert(p);h->released++;free(p);}
static unsigned le32(const unsigned char*p){return p[0]|(unsigned)p[1]<<8|(unsigned)p[2]<<16|(unsigned)p[3]<<24;}
static void put(unsigned char*p,unsigned n){p[0]=n;p[1]=n>>8;p[2]=n>>16;p[3]=n>>24;}
static unsigned char*read_all(const char*p,unsigned*n){FILE*f=fopen(p,"rb");assert(f);assert(!fseek(f,0,SEEK_END));long z=ftell(f);assert(z>0&&z<=(long)HB_LP_STX_MAX);assert(!fseek(f,0,SEEK_SET));unsigned char*b=malloc((unsigned)z+1);assert(b&&fread(b,1,(unsigned)z,f)==(unsigned)z);assert(!fclose(f));b[z]=0;*n=(unsigned)z;return b;}
static void save(const char*p,const void*b,unsigned n){FILE*f=fopen(p,"wb");assert(f&&fwrite(b,1,n,f)==n&&!fclose(f));}
int main(int argc,char**argv){assert(argc==2);struct harness h;memset(&h,0,sizeof h);h.root=argv[1];struct hb_lp_io io={&h,open_read,read_bytes,close_read,allocate,release};struct hb_lp_package p;assert(hb_lp_load(&io,"en",&p)&&p.setting==1&&p.stx_index==0&&!p.stock);assert(h.allocated==h.released);unsigned alloc=h.allocated;assert(hb_lp_load(&io,"jp",&p)&&p.stock&&p.setting==7&&h.allocated==alloc);assert(hb_lp_load(&io,"demo-fr",&p)&&p.setting==3&&p.stx_index==2);char resource[2048],meta[2048],active[2048];path(&h,"/contents/HOMEBREW/languages/en/wording.stx",resource);path(&h,"/contents/HOMEBREW/languages/en/language.ini",meta);path(&h,HB_LP_ACTIVE,active);unsigned bytes,mlen;unsigned char*data=read_all(resource,&bytes),*metadata=read_all(meta,&mlen);assert(hb_lp_stx(data,bytes));unsigned char*b=malloc(bytes);assert(b);memcpy(b,data,bytes);b[24]^=1;assert(hb_lp_stx(b,bytes));save(resource,b,bytes);assert(!hb_lp_load(&io,"en",&p));save(resource,data,bytes);memcpy(b,data,bytes);put(b+56,0xfffffffeu);assert(!hb_lp_stx(b,bytes));memcpy(b,data,bytes);put(b+56,0);assert(!hb_lp_stx(b,bytes));memcpy(b,data,bytes);put(b+48,7308);assert(!hb_lp_stx(b,bytes));memcpy(b,data,bytes);unsigned off=le32(b+56);assert(off<bytes-4);b[off]=0;b[off+1]=0xd8;b[off+2]='A';b[off+3]=0;assert(!hb_lp_stx(b,bytes));memcpy(b,data,bytes);off=le32(b+56);b[off]=0x2a;b[off+1]=0xe4;assert(!hb_lp_stx(b,bytes));memcpy(b,data,bytes);off=le32(b+56);assert(off+700<bytes);for(unsigned i=0;i<329;i++){b[off+i*2]='A';b[off+i*2+1]=0;}b[off+658]=b[off+659]=0;assert(!hb_lp_stx(b,bytes));memcpy(b,data,bytes);for(unsigned i=0;i<111;i++){b[off+i*2]=0;b[off+i*2+1]=0x4e;}b[off+222]=b[off+223]=0;assert(!hb_lp_stx(b,bytes));h.fail_alloc=1;assert(!hb_lp_load(&io,"en",&p));h.fail_alloc=0;h.fail_read=1;assert(!hb_lp_load(&io,"en",&p));h.fail_read=0;unsigned char original=metadata[0];metadata[0]='#';save(meta,metadata,mlen);assert(!hb_lp_load(&io,"en",&p));metadata[0]=original;save(meta,metadata,mlen);save(active,"en\n",3);assert(hb_lp_selected(&io,&p)&&!strcmp(p.id,"en"));save(active,"stock\n",6);assert(!hb_lp_selected(&io,&p));save(active,"../en\n",6);assert(!hb_lp_selected(&io,&p));assert(!hb_lp_load(&io,"missing",&p));char id[33];assert(hb_lp_choice("demo-fr\n",8,id)&&!strcmp(id,"demo-fr"));assert(!hb_lp_choice("en\0",3,id));assert(!hb_lp_id("../en")&&!hb_lp_id("Stock"));assert(h.allocated==h.released);for(unsigned i=0;i<8;i++)assert(!h.files[i]);free(b);free(metadata);free(data);puts("External language packs: dynamic IDs/base mappings, complete STX/SHA, malformed offsets/UTF16/missing text, corrupt/missing resources, allocation/read errors and descriptor cleanup passed");return 0;}
